<script setup>
import {computed,ref} from 'vue';
import {galleryImages} from '../../data/gallery.js';
import {withAttribution} from '../../data/galleryAttributions.js';
import registry from '../../data/gallery-attributions.json';
import {downloadJson,loadLocal,saveLocal} from '../../room/storage.js';
import {httpsLink} from '../../services/safeMedia.js';
import {assetUrl} from '../../data/site.js';
const query=ref(''),creator=ref('all'),message=ref(''),selected=ref('');
const images=galleryImages.map(withAttribution),creators=[...new Set(images.map(i=>i.creator).filter(Boolean))];
const rows=computed(()=>images.filter(i=>(creator.value==='all'||(creator.value==='pending'?!i.creator:i.creator===creator.value))&&(i.title+' '+i.creator+' '+i.credit).toLowerCase().includes(query.value.trim().toLowerCase())));
const draft=ref(loadLocal('hitori-room:source-draft:v1',{},v=>v&&typeof v==='object'?v:{}));
const creatorName=ref(''),original=ref(''),profile=ref('');
function choose(){const r=draft.value[selected.value]||registry[selected.value]||{};creatorName.value=r.creator||'';original.value=r.sourceUrl||'';profile.value=r.creatorUrl||'';}
function save(){try{if(!images.some(i=>i.id===selected.value))throw new Error('先选择图片。');if(!creatorName.value.trim())throw new Error('先填写核实后的作者名。');if(!httpsLink(original.value))throw new Error('请填写原作的HTTPS发布链接。');if(profile.value&&!httpsLink(profile.value))throw new Error('画师主页需要HTTPS链接。');draft.value={...draft.value,[selected.value]:{creator:creatorName.value.trim().slice(0,100),sourceUrl:httpsLink(original.value),creatorUrl:httpsLink(profile.value),status:'documented',method:'站主整理的原作来源',note:'请在发布前核对原发布页的署名。'}};if(!saveLocal('hitori-room:source-draft:v1',draft.value))throw new Error('草稿未能保存，请先导出来源表。');message.value='来源整理草稿已保存在本机；公开档案仍以已发布记录为准。';}catch(e){message.value=e.message;}}
function exportRegistry(){downloadJson({...registry,...draft.value},'hitori-gallery-attributions.json');message.value='已导出来源表，供站主核对并更新公开档案。';}
</script>
<template><section class="room-panel" aria-labelledby="sources-title"><p class="play-eyebrow">每一份喜欢，都值得认真署名</p><h2 id="sources-title">收藏来源档案</h2><p class="room-intro">已记录来源{{images.filter(i=>i.creator).length}}张，原作者待确认{{images.filter(i=>!i.creator).length}}张。未核实的收藏保留原有署名与水印，不推断作者或授权。</p><div class="room-fields"><label class="room-field">找图片或画师<input v-model="query" type="search" placeholder="搜索标题、作者或来源" maxlength="100"></label><label class="room-field">按画师浏览<select v-model="creator"><option value="all">全部画师与来源</option><option v-for="name in creators" :key="name" :value="name">{{name}}</option><option value="pending">原作者待确认</option></select></label></div><p class="room-hint">找到{{rows.length}}张</p><div class="resource-grid"><article v-for="i in rows" :key="i.id" class="resource-card"><RouterLink :to="{path:'/',query:{image:i.id},hash:'#gallery'}"><img :src="assetUrl(i.thumbnail||i.src)" :alt="i.alt" width="320" height="180" loading="lazy" style="width:100%;height:180px;object-fit:contain"><h3>{{i.title}}</h3></RouterLink><p>{{i.creator||'原作者待确认'}}</p><small>{{i.method}} · {{i.credit}}</small><div class="resource-actions"><a v-if="i.sourceUrl" :href="i.sourceUrl" target="_blank" rel="noopener noreferrer">原作发布页 ↗</a><a v-if="i.creatorUrl" :href="i.creatorUrl" target="_blank" rel="noopener noreferrer">画师主页 ↗</a></div></article></div><details style="margin-top:30px"><summary>站主整理来源表</summary><p class="room-intro">仅用于整理本机草稿；请依据原发布页面填写。导出来源表后，站主可以更新公开档案。</p><div class="source-form"><label class="room-field">选择收藏<select v-model="selected" @change="choose"><option value="">请选择图片</option><option v-for="i in images" :key="i.id" :value="i.id">{{i.title}} · {{i.id}}</option></select></label><label class="room-field">画师 / 原作者<input v-model="creatorName" maxlength="100"></label><label class="room-field">原作发布链接<input v-model="original" type="url" maxlength="1000"></label><label class="room-field">画师主页（选填）<input v-model="profile" type="url" maxlength="1000"></label><div class="room-actions"><button type="button" @click="save">保存来源草稿</button><button type="button" @click="exportRegistry">导出来源表 JSON</button></div></div><p class="room-status" role="status">{{message}}</p></details></section></template>
